"""Generate a compatibility inventory from configured CI jobs and explicitly measured STATUS rows.

Workflow configuration describes coverage, not a successful run or real-model compatibility. Dynamic matrices
are labelled unresolved rather than guessed. Evidence rows are copied verbatim; unmeasured claims are excluded.
"""

from __future__ import annotations

import argparse
import itertools
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[1]


def render(root: Path = ROOT) -> str:
    lines = ['# Compatibility / Compatibilidad', '',
             'Generated by `python scripts/compat_matrix.py`; do not edit manually. / No editar a mano.', '',
             '## Configured CI coverage / Cobertura configurada', '',
             'Configuration is not a passing run or a measurement with real weights. Dynamic runners stay unresolved.',
             '', '| Workflow | Job | Runner | Python |', '|---|---|---|---|']
    for path in sorted((root / '.github' / 'workflows').glob('*.yml')):
        workflow = yaml.safe_load(path.read_text(encoding='utf-8'))
        for name, job in workflow.get('jobs', {}).items():
            matrix = job.get('strategy', {}).get('matrix', {})
            if isinstance(matrix, dict):
                axes = {k: v for k, v in matrix.items() if k not in ('include', 'exclude') and isinstance(v, list)}
                rows = [dict(zip(axes, values, strict=True)) for values in itertools.product(*axes.values())] if axes else []
                rows = [row for row in rows if not any(all(row.get(k) == v for k, v in ex.items())
                                                     for ex in matrix.get('exclude', []))]
                rows += matrix.get('include', [])
            else:
                rows = []
            for row in rows or [{}]:
                runner = str(job.get('runs-on', 'unknown')).replace('${{ matrix.os }}', str(row.get('os', 'dynamic')))
                python = row.get('python', '')
                if not python:
                    python = next((step.get('with', {}).get('python-version', '') for step in job.get('steps', [])
                                   if str(step.get('uses', '')).startswith('actions/setup-python@')), '—')
                lines.append(f'| {path.name} | {name} | {runner} | {python or "—"} |')
    lines += ['', '## Measured evidence / Evidencia medida', '',
              'Only explicitly measured evidence rows and tables under “Measured with real weights” in STATUS.md.', '']
    measured = False
    in_table = False
    paragraph: list[str] = []
    caption: list[str] = []
    for line in (root / 'docs' / 'STATUS.md').read_text(encoding='utf-8').splitlines():
        if line.startswith('## '):
            paragraph, caption = [], []
            measured = line == '## Measured with real weights'
        is_row = line.startswith('|') and (measured or ('**measured**' in line.lower()
                                                       and 'not measured' not in line.lower()))
        if measured and not line.startswith('|'):
            if line.strip():
                paragraph.append(line)
            elif paragraph:
                caption, paragraph = paragraph, []
        if is_row:
            if not in_table and measured and caption and caption[0].startswith('**'):
                lines += [*caption, '']
                caption = []
            if not in_table and not measured:
                lines += ['| Area | Evidence | How to reproduce |', '|---|---|---|']
            lines.append(line)
        elif in_table:
            lines += ['', 'Source: [STATUS.md](STATUS.md#measured-with-real-weights).' if measured
                      else 'Source: [STATUS.md](STATUS.md#verified-with-evidence).', '']
        in_table = is_row
    return '\n'.join(lines).rstrip() + '\n'


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--out', type=Path, default=ROOT / 'docs' / 'COMPATIBILITY.md')
    args = parser.parse_args()
    content = render()
    if args.check:
        if not args.out.exists() or args.out.read_text(encoding='utf-8') != content:
            print('Compatibility is stale / Compatibilidad desactualizada: python scripts/compat_matrix.py')
            return 1
    else:
        args.out.write_text(content, encoding='utf-8')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
